python3 << 'PYEOF'
import sys
# --- manifest 注册（幂等） ---
mpath = 'app/src/main/AndroidManifest.xml'
s = open(mpath, encoding='utf-8').read()
entry = '<activity android:name=".ui.activity.LxUserPlaylistActivity" android:exported="false" />'
if 'LxUserPlaylistActivity' in s:
    print('manifest: LxUserPlaylistActivity 已注册，跳过')
else:
    if '</application>' not in s:
        print('❌ manifest 未找到 </application>，36 注册失败')
        sys.exit(1)
    s = s.replace('</application>', '        ' + entry + '\n    </application>', 1)
    open(mpath, 'w', encoding='utf-8').write(s)
    print('manifest: LxUserPlaylistActivity 已注册')

# --- 设置页临时入口（锚点：我的喜欢条目；36 须排在 15 之后） ---
hpath = 'app/src/main/java/com/github/tvbox/osc/ui/activity/MusicHomeActivity.kt'
try:
    h = open(hpath, encoding='utf-8').read()
except FileNotFoundError:
    print('❌ 未找到 MusicHomeActivity.kt：36 号必须排在 15 号之后运行')
    sys.exit(1)
if 'SettingItem("我的歌单"' in h:
    print('设置页: 我的歌单入口已存在，跳过')
else:
    anchor = 'SettingItem("我的喜欢"'
    if anchor not in h:
        print('❌ 设置页未找到「我的喜欢」锚点，临时入口写入失败')
        sys.exit(1)
    idx = h.index(anchor)
    end = h.index('},', idx) + 2
    entry = ('\n                // [36v1] 临时入口：我的歌单（第二步播放页接线后可去除）'
             '\n                SettingItem("我的歌单", "自建歌单") {'
             '\n                      context.startActivity(android.content.Intent(context, com.github.tvbox.osc.ui.activity.LxUserPlaylistActivity::class.java))'
             '\n                  },')
    h = h[:end] + entry + h[end:]
    if h.count('SettingItem("我的歌单"') != 1 or h.count('[36v1]') != 1:
        print('❌ 设置页临时入口写入后校验失败')
        sys.exit(1)
    open(hpath, 'w', encoding='utf-8').write(h)
    print('设置页: 我的歌单临时入口已添加')
PYEOF
echo "=== 36 完成 ==="
